// Bit Music Visualizer: dry part taps and mix gates, Float renderer only.
// Callback timestamp is in native 32 kHz samples, before DAC/reverb/analogue.
void (*bitmusicPartSample)(void *, unsigned int, Bit32u, float, float);
void *bitmusicPartContext;
Bit32u bitmusicMuteMask;
Bit32u bitmusicRandom; // Per-synth jitter state; no shared libc rand().
MT32EMU_EXPORT explicit Synth(ReportHandler *useReportHandler = NULL);

bitmusicPartSample = NULL;
bitmusicPartContext = NULL;
bitmusicMuteMask = 0;
bitmusicRandom = 1;
opened = false;
reverbOverridden = false;

FloatSample rightOut = (sample * rightPanValue) / 14.0f;
if (synth->bitmusicPartSample != NULL) {
	synth->bitmusicPartSample(synth->bitmusicPartContext, ownerPart,
		synth->getInternalRenderedSampleCount() + sampleNum, leftOut, rightOut);
}
if ((synth->bitmusicMuteMask & (1u << ownerPart)) != 0) {
	leftOut = rightOut = 0.0f;
}
*(leftBuf++) += leftOut;

// Independent deterministic jitter keeps audio and scopes synchronized.
Synth *synth = partial->getSynth();
synth->bitmusicRandom = synth->bitmusicRandom * 1664525u + 1013904223u;
counter = NOMINAL_PROCESS_TIMER_PERIOD_SAMPLES + ((synth->bitmusicRandom >> 16) & 3);
